package com.dy.artisan3d.data.mapperimport com.dy.artisan3d.data.model.artisan.about.ArtisanAboutDtoimport com.dy.artisan3d.domain.model.artisan.ArtisanAboutimport com.dy.artisan3d.domain.model.artisan.ArtisanEducationimport com.dy.artisan3d.domain.model.artisan.ArtisanPublicationimport com.dy.artisan3d.util.Constants.FILE_URLfun ArtisanAboutDto.toDomain(lang: String): ArtisanAbout {    val trans = translations?.get(lang) ?: translations?.values?.firstOrNull()    return ArtisanAbout(        id = id ?: 0,        fullName = trans?.name ?: "Noma'lum",        imageUrl = aboutImage?.let { FILE_URL+ it } ?: "",        birthDate = birthDate?.substringBefore("T") ?: "", // ISO formatdan faqat sanani olish        eduLevel = trans?.edu_level ?: "",        languages = trans?.languages?.split(",")?.map { it.trim() } ?: emptyList(),        educations = educations?.map { edu ->            ArtisanEducation(                id = edu.id ?: 0,                info = edu.translations?.get(lang)?.text                    ?: edu.translations?.values?.firstOrNull()?.text ?: ""            )        } ?: emptyList(),        publications = publications?.map { pub ->            val pTrans = pub.translations?.get(lang) ?: pub.translations?.values?.firstOrNull()            ArtisanPublication(                id = pub.id ?: 0,                title = pTrans?.title ?: "",                conference = pTrans?.conference_name ?: "",                date = pub.date ?: "",                url = pub.link ?: ""            )        } ?: emptyList()    )}